    Latitude = Math.round(Latitude);
    Longitude = Math.round(Longitude);

    let clouddesc="";
    if(CloudCover>87.5){
        clouddesc="Cloudy";
    }
    else if(CloudCover>62.5){
        clouddesc="Mostly Cloudy";
    }
    else if(CloudCover>37.5){
